<?php require 'config.php';$title=trim($_POST['title']??'');$date=$_POST['event_date']??'';if(!$title||!$date)exit('Missing event details');$poster=null;if(isset($_FILES['poster'])&&$_FILES['poster']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['poster'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>2*1024*1024)exit('Poster must be under 2 MB');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($types[$mime]))exit('Only JPG, PNG and WEBP are allowed');$poster=bin2hex(random_bytes(12)).'.'.$types[$mime];if(!move_uploaded_file($f['tmp_name'],__DIR__.'/uploads/'.$poster))exit('Upload failed');}$s=$db->prepare('INSERT INTO events(title,event_date,poster) VALUES(?,?,?)');$s->bind_param('sss',$title,$date,$poster);$s->execute();header('Location: index.php');?>